import{_ as o,a0 as r,w as p,s as d,I as t,x as n,a1 as a,A as s,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Arch Linux 中安裝 elementary OS 的 Pantheon 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中安裝 elementary OS 的 Pantheon 桌面 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中安裝 elementary OS 的 Pantheon 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中安裝 elementary OS 的 Pantheon 桌面 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221111.2 ⭐️⭐️ How to Install Elementary OS’s Pantheon Desktop in Arch Linux","title":"如何在 Arch Linux 中安裝 elementary OS 的 Pantheon 桌面","tag":"202211","desc":""},"relativePath":"202211/20221111.2 ⭐️⭐️ How to Install Elementary OS’s Pantheon Desktop in Arch Linux.md","filePath":"[post].md"}'),h={name:"202211/20221111.2 ⭐️⭐️ How to Install Elementary OS’s Pantheon Desktop in Arch Linux.md"};function g(u,e,m,k,b,y){const i=r("Link");return p(),d("div",null,[e[35]||(e[35]=t("h1",{id:"如何在-arch-linux-中安裝-elementary-os-的-pantheon-桌面",tabindex:"-1"},[n("如何在 Arch Linux 中安裝 elementary OS 的 Pantheon 桌面 "),t("a",{class:"header-anchor",href:"#如何在-arch-linux-中安裝-elementary-os-的-pantheon-桌面","aria-label":"Permalink to “如何在 Arch Linux 中安裝 elementary OS 的 Pantheon 桌面”"},"​")],-1)),e[36]||(e[36]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202211/27/104052h7iwfcw4larkio1i.jpg",alt:""})],-1)),e[37]||(e[37]=t("blockquote",null,[t("p",null,"Pantheon 是 elementary OS 的默認桌面環境。本快速指南解釋了在 Arch Linux 中安裝 Pantheon 桌面環境的步驟。")],-1)),e[38]||(e[38]=t("p",null,"Pantheon 是 elementary OS 使用的一個漂亮的桌面環境。它基於 GTK3（GTK4 移植正在進行中）和 Vala，是一個漂亮而乾淨的桌面，為你提供了一個精緻的 Linux 桌面體驗。",-1)),e[39]||(e[39]=t("p",null,"該桌面主要由 elementary OS 使用。elementary OS 提供了 Pantheon 桌面的修改版，它是基於 GNOME 的。",-1)),e[40]||(e[40]=t("p",null,"elementary OS 基於 Ubuntu LTS 版本。因此，在基於 Ubuntu 的發行版中安裝 Pantheon 桌面是超級容易的。這意味着如果你想在不安裝 elementary OS 的情況下體驗 Pantheon，在 Ubuntu 中這隻需要一兩個命令就可以安裝。",-1)),t("p",null,[e[1]||(e[1]=n("在 Fedora 中，你也可以使用組包進行安裝。然而，一個以 Fedora 為基礎，名為 ",-1)),a(i,{href:"https://www.debugpoint.com/ultramarine-linux-36/"},{default:s(()=>[...e[0]||(e[0]=[n("Ultramarine Linux",-1)])]),_:1}),e[2]||(e[2]=n(" 的發行版默認提供了它。",-1))]),e[41]||(e[41]=l('<p>但是，在 Arch Linux 中安裝 Pantheon 需要一些工作。它不是用簡單的 <code>pacman</code> 命令就能直接完成的，而且不能開箱即用。需要一些配置，這可能會破壞你的系統。</p><p>這裏我給你提供了在 Arch Linux 中安裝 Pantheon 桌面的指南和步驟。</p><p><strong>警告：</strong> 第一次可能不順利，所以我建議你在物理系統上安裝前先在虛擬機上進行。因為在 Arch 中安裝 Pantheon 並不像在 Arch Linux 中安裝 GNOME、Xfce 和 KDE Plasma 桌面那樣流暢。它還需要一些額外的手動配置。</p><p>下面是在 Arch Linux 中安裝 Pantheon 桌面的步驟。</p><h3 id="在-arch-linux-中安裝-pantheon-桌面" tabindex="-1">在 Arch Linux 中安裝 Pantheon 桌面 <a class="header-anchor" href="#在-arch-linux-中安裝-pantheon-桌面" aria-label="Permalink to “在 Arch Linux 中安裝 Pantheon 桌面”">​</a></h3><h4 id="第-1-步-安裝基礎系統" tabindex="-1">第 1 步：安裝基礎系統 <a class="header-anchor" href="#第-1-步-安裝基礎系統" aria-label="Permalink to “第 1 步：安裝基礎系統”">​</a></h4>',6)),t("p",null,[e[4]||(e[4]=n("確保你按照 ",-1)),a(i,{href:"https://www.debugpoint.com/archinstall-guide/"},{default:s(()=>[...e[3]||(e[3]=[n("本指南的自動 archinstall 腳本",-1)])]),_:1}),e[5]||(e[5]=n(" 安裝了 Arch Linux 基礎系統。如果你已經在完成了 Arch 安裝，你可以跳過這一步，按照下一步進行。",-1))]),e[42]||(e[42]=l('<h4 id="第-2-步-更新你的系統" tabindex="-1">第 2 步：更新你的系統 <a class="header-anchor" href="#第-2-步-更新你的系統" aria-label="Permalink to “第 2 步：更新你的系統”">​</a></h4><p>在你的 Arch 中打開一個終端。並通過運行以下命令確保系統是最新的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Syu</span></span></code></pre></div><h4 id="第-3-步-安裝-yay-aur-助手" tabindex="-1">第 3 步：安裝 yay AUR 助手 <a class="header-anchor" href="#第-3-步-安裝-yay-aur-助手" aria-label="Permalink to “第 3 步：安裝 yay AUR 助手”">​</a></h4>',4)),t("p",null,[e[7]||(e[7]=n("Pantheon 所需的許多包在 Arch 官方倉庫中不可用。它們存在於 Arch 用户倉庫（AUR）中。因此你需要安裝 ",-1)),e[8]||(e[8]=t("code",null,"yay",-1)),e[9]||(e[9]=n(" 以獲得額外的軟件包。按照 ",-1)),a(i,{href:"https://www.debugpoint.com/install-yay-arch/"},{default:s(()=>[...e[6]||(e[6]=[n("本指南安裝 yay AUR 助手",-1)])]),_:1}),e[10]||(e[10]=n("。",-1))]),e[43]||(e[43]=t("h4",{id:"第-4-步-在-arch-linux-中安裝-pantheon-桌面",tabindex:"-1"},[n("第 4 步：在 Arch Linux 中安裝 Pantheon 桌面 "),t("a",{class:"header-anchor",href:"#第-4-步-在-arch-linux-中安裝-pantheon-桌面","aria-label":"Permalink to “第 4 步：在 Arch Linux 中安裝 Pantheon 桌面”"},"​")],-1)),e[44]||(e[44]=t("p",null,"使用以下命令安裝以下軟件包。這些是 Arch 官方倉庫中可用的必需軟件包，包括所有必要的組件、wingpanel、圖標和壁紙。",-1)),t("ul",null,[t("li",null,[a(i,{href:"https://wiki.archlinux.org/index.php/Pantheon"},{default:s(()=>[...e[11]||(e[11]=[n("pantheon",-1)])]),_:1})]),e[12]||(e[12]=t("li",null,"lightdm-pantheon-greeter",-1)),e[13]||(e[13]=t("li",null,"sound-theme-elementary",-1)),e[14]||(e[14]=t("li",null,"switchboard",-1)),e[15]||(e[15]=t("li",null,"lightdm-gtk-greeter",-1)),e[16]||(e[16]=t("li",null,"elementary-icon-theme",-1)),e[17]||(e[17]=t("li",null,"elementary-wallpapers",-1)),e[18]||(e[18]=t("li",null,"pantheon-applications-menu",-1)),e[19]||(e[19]=t("li",null,"wingpanel-indicator-session",-1)),e[20]||(e[20]=t("li",null,"wingpanel-indicator-datetime",-1))]),e[45]||(e[45]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed pantheon lightdm-pantheon-greeter sound-theme-elementary switchboard lightdm-gtk-greeter elementary-icon-theme elementary-wallpapers pantheon-applications-menu wingpanel-indicator-session wingpanel-indicator-datetime inter-font firefox</span></span></code></pre></div><p>從 Arch 用户倉庫安裝以下包。這些是 Arch 官方倉庫中不可用的一些附加包。這些可能需要一些時間來安裝。</p><ul><li>pantheon-session-git</li><li>gnome-settings-daemon-elementary</li><li>pantheon-default-settings</li><li>switchboard-plug-pantheon-tweaks-git</li><li>urutau-icons-git</li><li>pantheon-dock-git</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yay -S pantheon-session-git pantheon-default-settings switchboard-plug-pantheon-tweaks-git urutau-icons-git pantheon-dock-git</span></span></code></pre></div><p>下一步是安裝顯示服務器和管理器。使用 <code>lightdm</code> 作為 Arch 中 Pantheon 的顯示管理器。我嘗試將其他顯示管理器與 Pantheon 一起使用，但結果並不理想。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed xorg lightdm</span></span></code></pre></div><h4 id="第-5-步-配置" tabindex="-1">第 5 步：配置 <a class="header-anchor" href="#第-5-步-配置" aria-label="Permalink to “第 5 步：配置”">​</a></h4><p>默認歡迎程序需要一些修改。運行以下命令以檢查可用會話。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -1 /usr/share/xgreeters</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/02/greeters-list.jpg" alt="greeters 列表"></p><p>打開 lightdm 配置文件並將 <code>greeter-session</code> 更改為 <code>io.elementary.greeter</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/lightdm/lightdm.conf</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>greeter-session=io.elementary.greeter</span></span></code></pre></div><p>保存並關閉文件（<code>CTRL+O</code>、<code>回車</code> 和 <code>CTRL+X</code>）。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/02/lightdm-conf.jpg" alt="lightdm 配置"></p><p>在 systemd 中啓用顯示管理器和網絡管理器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable lightdmsystemctl enable NetworkManager</span></span></code></pre></div><p>重啓系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl reboot</span></span></code></pre></div><p>如果一切順利，你應該會看到以下登錄屏幕（我知道，它看起來一點也不酷）。從頂部下拉菜單更改會話並使用用户名和密碼登錄。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/02/Login-screen-Pantheon-in-Arch.jpg" alt="Pantheon 在 Arch 中的登錄頁面"></p><h4 id="第-6-步-安裝後配置" tabindex="-1">第 6 步：安裝後配置 <a class="header-anchor" href="#第-6-步-安裝後配置" aria-label="Permalink to “第 6 步：安裝後配置”">​</a></h4><p>當我第一次登錄到我的測試系統時，很多東西都不起作用。以下是列表及其可能的解決方案。</p><p>a、<strong>壁紙</strong>：壁紙模組似乎根本不起作用。因此，默認情況下沒有壁紙。甚至“更改壁紙”選項也沒有打開。如果遇到這種情況，請安裝 <code>dconf</code> 編輯器並通過以下步驟更改壁紙。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed dconf-editor</span></span></code></pre></div><p>接着從菜單啓動 dconf 編輯器。進入 <code>org &gt; gnome &gt; desktop &gt; background &gt; picture-uri</code>。關閉默認值並添加自定義值 <code>file:////usr/share/backgrounds/Ashim DSilva.jpg</code>。你也可以使用任何其他圖像。保存並關閉。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/02/Change-background-property-using-dconf-editor.jpg" alt="使用 dconf-editor 更改背景屬性"></p><p>b、<strong>圖標</strong>：通過 “<ruby>設置<rt>Settings</rt></ruby> &gt; <ruby>優化<rt>Tweaks</rt></ruby>” 更改圖標。然後將圖標和光標更改為 <code>urutau-icons</code>。</p><p>在完成所有配置和安裝之後，你應該已經在 Arch Linux 中設置了 Pantheon 桌面。這是我的測試機的截圖。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/02/Pantheon-Desktop-in-Arch-Linux-1.jpg" alt="Arch Linux 中的 Pantheon 桌面"></p><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>我希望本指南能幫助你最終在 Arch Linux 中安裝 Pantheon 桌面。我花了幾天時間才終於能夠將各個部分組合在一起並使它們發揮作用。</p><p>儘管一些小功能仍然無法使用，但有一個可用的 Pantheon 桌面。</p><p>唯一讓我驚喜的是 Pantheon 在 Arch 中的表現。在我的同一台測試機上，elementary OS 安裝不是那麼快。但 Pantheon 基礎版在 Arch 中的速度比原始 elementary OS 快。如果你喜歡 Pantheon，可以試試。</p><p>如果你遇到任何錯誤，請使用下面的評論欄告訴我。</p><hr>',36)),t("p",null,[e[22]||(e[22]=n("via: ",-1)),a(i,{href:"https://www.debugpoint.com/pantheon-arch-linux-install/"},{default:s(()=>[...e[21]||(e[21]=[n("https://www.debugpoint.com/pantheon-arch-linux-install/",-1)])]),_:1})]),t("p",null,[e[26]||(e[26]=n("作者：",-1)),a(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:s(()=>[...e[23]||(e[23]=[n("Arindam",-1)])]),_:1}),e[27]||(e[27]=n(" 選題：",-1)),a(i,{href:"https://github.com/lkxed"},{default:s(()=>[...e[24]||(e[24]=[n("lkxed",-1)])]),_:1}),e[28]||(e[28]=n(" 譯者：",-1)),a(i,{href:"https://github.com/geekpi"}),e[29]||(e[29]=n(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:s(()=>[...e[25]||(e[25]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[32]||(e[32]=n("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[30]||(e[30]=[n("LCTT",-1)])]),_:1}),e[33]||(e[33]=n(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:s(()=>[...e[31]||(e[31]=[n("Linux中國",-1)])]),_:1}),e[34]||(e[34]=n(" 榮譽推出",-1))])])}const w=o(h,[["render",g]]);export{x as __pageData,w as default};
